// Adapted from Eight Aces dist/sw.js. Generated by scripts/build-offline.mjs.
const cachePrefix = 'kierki-offline-' + self.registration.scope;
const cacheName = cachePrefix + '__VERSION__';
const scope = self.registration.scope;
const assetNames = __ASSETS__;
const assets = new Set(assetNames.map(name => new URL(name, scope).href));

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(cacheName);
    // Sites redirects index.html to /. A redirected Response cannot be reused
    // for an offline navigation with redirect mode "manual". Store its body as
    // a plain response; fetch all assets successfully before writing the cache.
    const entries = await Promise.all([...assets].map(async url => {
      const response = await fetch(new Request(url, { cache: 'reload' }));
      if (!response.ok) throw new Error('Offline asset unavailable: ' + url);
      const body = await response.arrayBuffer();
      return [url, new Response(body, { status: response.status, headers: response.headers })];
    }));
    await Promise.all(entries.map(([url, response]) => cache.put(url, response)));
  })());
  // Let current clients finish before activating the updated worker.
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(key => key.startsWith(cachePrefix) && key !== cacheName)
      .map(key => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  url.search = '';
  url.hash = '';
  const key = url.href === scope ? new URL('index.html', scope).href : url.href;
  // Only this game's explicit resources; external links and analytics stay online.
  if (!assets.has(key)) return;
  event.respondWith((async () => {
    const cache = await caches.open(cacheName);
    return await cache.match(key) ?? fetch(event.request);
  })());
});
